public int Get_Feature_WOkresie(Context cx) {
    // okres z filtra "Okres" listy pracowników (obiekt parametrów widoku dziedziczy po OkresContext)
    OkresContext parametryListy;
    FromTo okres = FromTo.Empty;
    if (cx.Get<OkresContext>(out parametryListy) && parametryListy != null)
        okres = parametryListy.Okres;
    // kod wspólny: Dodatkowy kod kompilacji "A1Przypomnienia"
    // Int zamiast Bool: filtr widoku "[Features.WOkresie] = 1" (porównanie liczb jak w kolorach)
    return Soneta.Runtime.Database.Business.TblCodeFiles.Przypomnienia.WOkresie(Row, okres) ? 1 : 0;
}
